import { CHARACTER_KEYS } from '../Keys.js';

/** @typedef {import('../Keys.js').CharacterKey} CharacterKey */

/**
 * Basic-attack animation timing for one character, in frames (= battle ticks). Generated by
 * Suikoden-Bizhawk-HUD's scripts/AttackTimingWalker.py from the character's 04_play/<code>.bin
 * animation scripts (outputs/AttackTimingsClean.json), live-verified against the Zombie Dragon
 * fight for Viktor, Gremio, McDohl, Cleo, Camille and Tai Ho. Same shape as EnemyAttackTiming's
 * core fields; every character has one hit, no animation-time rand() and nothing untimed.
 *
 * Frame convention: t0 = the tick the attack executor starts the attack script (the same tick
 * as the hit and crit rolls). Each tick runs the turn coroutine first (turn rolls, dispatch,
 * damage rolls), then the animation pass. A busy bit that clears "at" frame F clears in F's
 * animation pass, so turn rolls and enemy target checks first see that combatant free at F + 1.
 *
 * @typedef {Object} CharacterAttackTiming
 * @property {string} name - Display name, as in CHARACTERS.
 * @property {number} id - Roster ID (byte 0 of the character's 04_play file header).
 * @property {number} damage - t0 -> the damage roll (calc_damage's rand()), the frame after the
 *   attack script's impact. The target's reaction starts on this tick.
 * @property {number} free - t0 -> the frame this character's busy bits clear (the attack script
 *   finishes, then the return-to-position script runs and clears them).
 * @property {number} reaction - The damage roll -> the frame the TARGET's busy bit 8 clears
 *   (this character's reaction script, played on whoever it hits; the same on a crit and
 *   against every target). A Fire or Thunder Rune Piece replaces it with a fixed 34.
 */

